    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal band rows are identified by enclosed one-cell gaps between
    # matching colored cells. Fill each gap and record its color as a source.
    bars = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                bars.setdefault(r, {})[c] = row[c - 1]
                out[r][c] = row[c - 1]

    # A horizontal band's gap projects upward until the previous band gap in
    # that column (or the top edge). Bands are processed from top to bottom.
    columns = {c for gaps in bars.values() for c in gaps}
    for c in columns:
        events = sorted((r, gaps[c]) for r, gaps in bars.items() if c in gaps)
        for i, (r, color) in enumerate(events):
            upper = events[i - 1][0] if i else -1
            for rr in range(upper + 1, r):
                if grid[rr][c] == 0:
                    out[rr][c] = color

    # Colored vertical strokes in the lower area project upward to the row
    # immediately below the lowest horizontal band, without crossing it.
    if bars:
        lowest_bar = max(bars)
        for c in range(w):
            # Find contiguous colored run(s) below the last horizontal band.
            r = h - 1
            while r > lowest_bar:
                if grid[r][c] == 0:
                    r -= 1
                    continue
                color = grid[r][c]
                start = r
                while r > lowest_bar and grid[r][c] == color:
                    r -= 1
                # This whole run is retained; fill the gap upward from its top.
                for rr in range(r, lowest_bar, -1):
                    if grid[rr][c] == 0:
                        out[rr][c] = color
                # Continue scanning higher for a distinct run in the lower panel.
    return out

